    valid_config = 0;
} else if (wm_config.required < 1 || wm_config.required > 20) {
    valid_config = 0;
}

// 2. Compute momentum if valid
if (valid_config) {
    if (adcs_wheel_momentum(wm_input.wheels, wm_input.count, &h_body) != ADCS_OK) {
        valid_config = 0;
    }
}

// 3. Handle Fault condition
if (!valid_config) {
    wm_output.mode = WM_FAULT;
    wm_output.good = 0;
    wm_output.momentum = h_body; // Output whatever was computed before failure or zero
    wm_output.error = error_vec;
    wm_output.error_norm = err_norm;
    wm_output.error_energy = err_energy;
    wm_state.mode = WM_FAULT;
    wm_state.good = 0;
    return;
}

