        if (err_norm <= wm_config.stop) {
            wm_output.good = wm_state.good + 1;
            if (wm_output.good >= wm_config.required) {
                wm_output.mode = WM_COMPLETE;
            } else {
                wm_output.mode = WM_ACTIVE;
            }
        } else {
            wm_output.good = 0;
            wm_output.mode = WM_ACTIVE;
        }
    } else if (wm_output.mode == WM_COMPLETE) {
        if (err_norm < wm_config.restart) {
            wm_output.mode = WM_COMPLETE;
            // Good is preserved (already copied from state)
        } else {
            wm_output.mode = WM_ACTIVE;
            wm_output.good = 0;
